<?php if($doc['kind']==='invoice'):$notes=all("SELECT id,number,total,created_at FROM documents WHERE source_invoice_id=? AND kind='credit' ORDER BY id",[$doc['id']]);?><section class="panel padded commerce-block"><h2>Avoirs liés à cette facture</h2><p class="small muted">La facture reste inchangée. Les avoirs corrigent les montants dus et le chiffre d’affaires.</p><?php if($summary['credited']<cents($doc['total'])):?><a class="btn secondary" href="<?=e(url('credit_form',['id'=>$doc['id']]))?>">Préparer un avoir</a><?php endif?><?php foreach($notes as $note):?><div class="document-row"><a class="record-title" href="<?=e(url('document',['id'=>$note['id']]))?>"><?=e($note['number'])?></a><span><?=e(money($note['total']))?> à déduire</span><a class="btn secondary" href="<?=e(url('document',['id'=>$note['id'],'download'=>'pdf']))?>">↓ PDF</a></div><?php endforeach?><?php if($summary['available']>0):?><p class="notice info">Solde en faveur du client : <?=e(money(decimalString($summary['available'],2)))?>. Aucun remboursement enregistré par cet avoir ; règlement à traiter séparément.</p><?php endif?><?php if($summary['pending']>$summary['balance']):?><p class="notice info">Les règlements en attente dépassent le nouveau reste dû. Vérifiez-les dans la commande avant confirmation.</p><?php endif?></section><?php elseif($doc['kind']==='credit'):?><div class="notice info commerce-block">Avoir à déduire de la facture <a href="<?=e(url('document',['id'=>$doc['source_invoice_id']]))?>"><?=e($s['source_invoice']['number'])?></a>. Aucun remboursement ni mouvement de stock automatique.</div><?php endif?>
